import type { RouteNamedMap } from 'vue-router/auto-routes'
import type { NuxtLinkProps } from '#app'

// Generated by `experimental.typedPages`. Imported from
// `vue-router/auto-routes` on purpose: `RouteLocationRaw` from 'vue-router'
// resolves to the root `vue-router` dependency, which the generated route
// types don't reach, so it accepts any route name.

/** Every route under `app/pages/[countryCode]/`. */
export type CountryRouteName = {
  [
    K in keyof RouteNamedMap
  ]: 'countryCode' extends keyof RouteNamedMap[K]['paramsRaw'] ? K : never
}[keyof RouteNamedMap]

type ParamsWithoutCountry<K extends CountryRouteName> = Omit<
  RouteNamedMap[K]['paramsRaw'],
  'countryCode'
>

/**
 * A named route under `/[countryCode]`, without `countryCode`:
 * `useCountryLink()` / `AppLink` add it from the current country.
 */
export type AppRoute = {
  [K in CountryRouteName]: ([keyof ParamsWithoutCountry<K>] extends [never]
    ? { name: K; params?: Record<string, never> }
    : { name: K; params: ParamsWithoutCountry<K> }) & {
    query?: Record<string, string>
    hash?: string
  }
}[CountryRouteName]

/**
 * What `AppLink`/`AppLinkButton` accept: a path relative to `/[countryCode]`
 * (static pages, CMS-provided URLs) or a named route (routes with params).
 */
export type AppLinkTarget = string | AppRoute

/**
 * `AppRoute` with `countryCode` filled in, typed as the location
 * `NuxtLink`/`navigateTo` accept.
 */
export type CountryRouteLocation = Exclude<
  NonNullable<NuxtLinkProps['to']>,
  string
>
